function loadLocalJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return parsed ?? fallback;
  } catch (e) {
    return fallback;
  }
}

function saveLocalJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {}
}

function safeText(val) {
  if (val === null || val === undefined) return '—';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
    return String(val);
  }
  if (Array.isArray(val)) {
    return val.map((item) => safeText(item)).join(', ');
  }
  if (typeof val === 'object') {
    return Object.entries(val)
      .map(([k, v]) => `${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`)
      .join(' • ');
  }
  return String(val);
}

function getStaffTitle(st) {
  return st?.position || st?.roleTitle || 'Executive Staff';
}

function getStaffTerritoryLabel(st) {
  if (!st) return 'All Territories (Global)';
  if (typeof st.territoryName === 'string' && st.territoryName) return st.territoryName;
  const states = st.territoryScope?.states;
  if (Array.isArray(states) && states.length > 0) {
    return states.includes('ALL') ? 'All Territories (Global)' : states.join(', ');
  }
  return 'All Territories (Global)';
}

