  const handleProcessCancellationAndRefund = (order, reason, deductionPolicy) => {
    if (!order) return;
    const isShipped = order.status === 'Shipped';
    const deliveryDeduction = (deductionPolicy === 'DEDUCT_DELIVERY' || (deductionPolicy === 'AUTO' && isShipped)) ? 1500 : 0;
    const originalTotal = Number(order.total) || 0;
    const refundAmount = Math.max(0, originalTotal - deliveryDeduction);

    handleOrderAction(order.rawId, 'Canceled');

    recordAudit({
      module: 'Customer Care & Resolution',
      actionType: 'CANCEL_ORDER_AND_REFUND',
      targetEntity: `Order #${order.rawId || order.id} (${order.customerName})`,
      previousValue: order.status,
      newValue: 'CANCELED & REFUNDED',
      reason: `Reason: ${reason}. Refunded ${formatNaira(refundAmount)} (Delivery Deduction: ${formatNaira(deliveryDeduction)})`,
    });

    if (notify) {
      notify(
        'Order Canceled & Refund Processed',
        `Order #${order.rawId || order.id} canceled. ${formatNaira(refundAmount)} refunded to customer.`,
        'success'
      );
    }
    setCancelRefundModalOrder(null);
  };

