    const hasCac = Boolean(matchedStore?.cacNumber || matchedStore?.cacDoc || storeOrOrder.cacNumber || storeOrOrder.cacDoc);
    const cacNumber = hasCac ? (matchedStore?.cacNumber || storeOrOrder.cacNumber) : 'Not Uploaded';
    const cacUploaded = hasCac;

    const hasNin = Boolean(matchedStore?.directorNIN || matchedStore?.ninDoc || storeOrOrder.directorNIN || storeOrOrder.directorNin || storeOrOrder.nin);
    const directorNIN = hasNin ? (matchedStore?.directorNIN || storeOrOrder.directorNIN || storeOrOrder.directorNin || storeOrOrder.nin) : 'Not Uploaded';
    const ninUploaded = hasNin;

    const directorName = matchedStore?.directorName || matchedStore?.ownerName || storeOrOrder.directorName || storeOrOrder.contactPerson || 'Not Uploaded';
