                              background: isDeactivated ? '#DCFCE7' : '#FEE2E2',
                              border: `1px solid ${isDeactivated ? '#86EFAC' : '#FCA5A5'}`,
                              color: isDeactivated ? '#15803D' : '#B91C1C',
