                      color: '#94A3B8',
                      fontSize: '9.5px',
                      fontWeight: 800,
                      cursor: 'pointer',
                      marginBottom: isCollapsed ? '0' : '8px',
                      letterSpacing: '0.04em',
                      transition: 'all 0.15s ease',
