                            background: isActive ? BRAND.sidebarActivePill : 'transparent',
                            color: isActive ? '#FFFFFF' : BRAND.sidebarTextMuted,
                            fontWeight: isActive ? 600 : 500,
                            fontSize: '13px',
                            textAlign: 'left',
                            border: 'none',
                            cursor: 'pointer',
                            transition: 'background 0.15s, color 0.15s',
