                      color: operationsQuickTab === 'ALL' ? '#FFFFFF' : BRAND.textBody,
                      border: '1px solid ' + (operationsQuickTab === 'ALL' ? BRAND.logoDeepGreen : BRAND.cardBorder),
                      fontSize: '12px',
